DECLARE @t NVARCHAR(128);
DECLARE c CURSOR LOCAL FAST_FORWARD FOR
  SELECT OBJECT_NAME(object_id) FROM sys.identity_columns
  WHERE last_value IS NOT NULL AND OBJECT_NAME(object_id) IN ('anh_hoan_tien', 'hoan_tien', 'chi_tiet_tra_hang_lo', 'anh_yeu_cau_tra_hang', 'yeu_cau_tra_hang', 'danh_gia', 'hoa_don_chi_tiet_lo', 'thanh_toan_hoa_don', 'lich_su_don_hang', 'hoa_don_chi_tiet', 'thong_bao', 'hoa_don', 'khach_hang_phieu_giam_gia', 'chi_tiet_dot_giam_gia', 'dot_giam_gia', 'phieu_giam_gia', 'chi_tiet_gio_hang', 'gio_hang', 'tin_nhan_ho_tro', 'phien_ho_tro', 'tin_nhan_chat_ai', 'phien_chat_ai', 'lich_su_hanh_vi', 'san_pham_yeu_thich', 'ket_qua_quiz', 'dap_an_quiz', 'cau_hoi_quiz', 'chi_tiet_routine', 'routine', 'routine_combo_chi_tiet', 'routine_combo', 'luat_goi_y', 'chi_tiet_phieu_nhap', 'phieu_nhap', 'lo_hang', 'anh_san_pham', 'chi_tiet_san_pham', 'san_pham_thanh_phan', 'san_pham_cong_dung', 'san_pham_loai_da', 'san_pham', 'nha_cung_cap', 'thanh_phan', 'cong_dung', 'dang_san_pham', 'mau_sac', 'danh_muc', 'thuong_hieu', 'dia_chi_khach_hang', 'khach_hang', 'nhan_vien', 'phuong_thuc_thanh_toan', 'loai_da', 'vai_tro', 'cau_hoi_thuong_gap', 'du_lieu_uv', 'banner_trang_chu');
OPEN c; FETCH NEXT FROM c INTO @t;
WHILE @@FETCH_STATUS = 0 BEGIN DBCC CHECKIDENT (@t, RESEED, 0) WITH NO_INFOMSGS; FETCH NEXT FROM c INTO @t; END
CLOSE c; DEALLOCATE c;
GO
