SET IDENTITY_INSERT san_pham ON;
INSERT INTO san_pham (id, ma_san_pham, ten, id_thuong_hieu, id_danh_muc, id_dang_san_pham, chi_so_spf, chi_so_pa, loai_chong_nang, khang_nuoc, mo_ta, trang_thai, noi_bat, ngay_tao) VALUES
(1, N'SP01', N'Anessa Perfect UV Sunscreen Skincare Milk', 1, 7, 1, N'SPF50+', N'PA++++', N'LAI', 1, N'Sữa chống nắng bán chạy nhất của Anessa với công nghệ Auto Booster — màng chống nắng bền hơn khi gặp nước, mồ hôi. Kết cấu sữa lỏng, thấm nhanh, phù hợp đi biển và hoạt động ngoài trời.', 1, 1, '2025-01-06 09:07:00'),
(2, N'SP02', N'Anessa Perfect UV Sunscreen Skincare Gel', 1, 1, 3, N'SPF50+', N'PA++++', N'HOA_HOC', 1, N'Gel chống nắng mỏng nhẹ, mát da, không bết dính. Chứa thành phần dưỡng ẩm, phù hợp da dầu và da hỗn hợp dùng hằng ngày.', 1, 1, '2025-01-06 09:14:00'),
(3, N'SP03', N'La Roche-Posay Anthelios UVMune 400 Invisible Fluid', 2, 5, 7, N'SPF50+', N'PA++++', N'HOA_HOC', 1, N'Kem chống nắng dạng fluid siêu mỏng, chứa màng lọc Mexoryl 400 chống tia UVA dài. Không màu, không vệt trắng, phù hợp da nhạy cảm.', 1, 1, '2025-01-06 09:21:00'),
(4, N'SP04', N'La Roche-Posay Anthelios XL Dry Touch Gel-Cream', 2, 4, 3, N'SPF50+', N'PA++++', N'HOA_HOC', 0, N'Gel-cream kiềm dầu, cho bề mặt khô ráo, lì nhẹ suốt nhiều giờ. Không gây bít tắc, phù hợp da dầu mụn.', 1, 0, '2025-01-06 09:28:00'),
(5, N'SP05', N'La Roche-Posay Anthelios Clear Skin Oil Free SPF60', 2, 4, 8, N'SPF60', NULL, N'HOA_HOC', 0, N'Phiên bản thị trường Mỹ, kết cấu lotion khô thoáng, thấm hút dầu thừa. Nhãn Mỹ không ghi chỉ số PA (ghi Broad Spectrum).', 1, 0, '2025-01-06 09:35:00'),
(6, N'SP06', N'Vichy Capital Soleil UV-Age Daily SPF50+', 3, 1, 7, N'SPF50+', N'PA++++', N'HOA_HOC', 0, N'Kem chống nắng dạng fluid chống lão hóa do ánh nắng, chứa Niacinamide. Kết cấu mỏng như nước, không nhờn.', 1, 1, '2025-01-06 09:42:00'),
(7, N'SP07', N'Vichy Capital Soleil Beach Protect Hydrating Milk SPF50', 3, 2, 1, N'SPF50', NULL, N'HOA_HOC', 1, N'Sữa chống nắng toàn thân kháng nước, cấp ẩm cho da khi đi biển. Hàng châu Âu, nhãn không ghi PA.', 1, 0, '2025-01-06 09:49:00'),
(8, N'SP08', N'Skin1004 Madagascar Centella Air-Fit Suncream Plus', 4, 5, 2, N'SPF50+', N'PA++++', N'VAT_LY', 0, N'Kem chống nắng vật lý chứa chiết xuất rau má Madagascar, dịu nhẹ cho da nhạy cảm, không cay mắt.', 1, 1, '2025-01-06 09:56:00'),
(9, N'SP09', N'Skin1004 Madagascar Centella Tone Brightening Tone-Up Sunscreen', 4, 3, 2, N'SPF50+', N'PA++++', N'LAI', 0, N'Kem chống nắng nâng tông hồng nhẹ, làm sáng da tức thì, có thể dùng như lớp lót trang điểm.', 1, 1, '2025-01-06 10:03:00'),
(10, N'SP10', N'Sunplay Skin Aqua Tone Up UV Essence', 5, 3, 4, N'SPF50+', N'PA++++', N'HOA_HOC', 0, N'Tinh chất chống nắng nâng tông bán chạy, có 2 màu: tím lavender cho da vàng xỉn và xanh bạc hà cho da đỏ, không đều màu.', 1, 1, '2025-01-06 10:10:00'),
(11, N'SP11', N'Sunplay Skin Aqua Clear White SPF50+', 5, 2, 1, N'SPF50+', N'PA++++', N'HOA_HOC', 1, N'Sữa chống nắng dưỡng sáng da, dùng được cho cả mặt và toàn thân, giá tốt.', 1, 0, '2025-01-06 10:17:00'),
(12, N'SP12', N'Bioré UV Aqua Rich Watery Essence', 6, 1, 4, N'SPF50+', N'PA++++', N'HOA_HOC', 0, N'Tinh chất chống nắng thấm nhanh như nước, không nhờn rít, lựa chọn quen thuộc cho da dầu hằng ngày.', 1, 1, '2025-01-06 10:24:00'),
(13, N'SP13', N'Bioré UV Aqua Rich Watery Gel', 6, 2, 3, N'SPF50+', N'PA++++', N'HOA_HOC', 0, N'Gel chống nắng mát lạnh, dùng được cho cả mặt và toàn thân.', 1, 0, '2025-01-06 10:31:00'),
(14, N'SP14', N'Innisfree Tone Up No Sebum Sunscreen', 9, 3, 2, N'SPF50+', N'PA++++', N'LAI', 0, N'Kem chống nắng nâng tông kiềm dầu, chứa bột khoáng hút dầu, cho lớp nền sáng mịn.', 1, 0, '2025-01-06 10:38:00'),
(15, N'SP15', N'Innisfree Intensive Triple-Shield Sunscreen', 9, 7, 2, N'SPF50+', N'PA++++', N'HOA_HOC', 1, N'Kem chống nắng bảo vệ 3 lớp: tia UV, ánh sáng xanh và bụi mịn, kháng nước tốt.', 1, 0, '2025-01-06 10:45:00'),
(16, N'SP16', N'EltaMD UV Clear Broad-Spectrum SPF46', 8, 4, 8, N'SPF46', NULL, N'LAI', 0, N'Kem chống nắng được bác sĩ da liễu khuyên dùng cho da mụn, nhạy cảm; chứa Zinc Oxide và Niacinamide. Hàng Mỹ, nhãn không ghi PA.', 1, 1, '2025-01-06 10:52:00'),
(17, N'SP17', N'EltaMD UV Daily Broad-Spectrum SPF40', 8, 10, 8, N'SPF40', NULL, N'LAI', 0, N'Kem chống nắng dưỡng ẩm với Hyaluronic Acid cho da khô. Hàng Mỹ, nhãn không ghi PA.', 1, 0, '2025-01-06 10:59:00'),
(18, N'SP18', N'Eucerin Sun Gel-Cream Oil Control Dry Touch SPF50+', 7, 4, 3, N'SPF50+', NULL, N'HOA_HOC', 0, N'Gel-cream kiểm soát dầu đến 8 giờ, không gây mụn. Hàng châu Âu, nhãn không ghi PA.', 1, 0, '2025-01-06 11:06:00'),
(19, N'SP19', N'Eucerin Sun Pigment Control Fluid SPF50+', 7, 1, 7, N'SPF50+', NULL, N'HOA_HOC', 0, N'Fluid chống nắng hỗ trợ giảm thâm nám do ánh nắng. Hàng châu Âu, nhãn không ghi PA.', 1, 0, '2025-01-06 11:13:00'),
(20, N'SP20', N'Beauty of Joseon Relief Sun: Rice + Probiotics', 10, 10, 2, N'SPF50+', N'PA++++', N'HOA_HOC', 0, N'Kem chống nắng chứa chiết xuất gạo và lợi khuẩn, dưỡng ẩm, cho lớp nền căng bóng tự nhiên.', 1, 1, '2025-01-06 11:20:00');
