/* ---------- 10. ĐÁNH GIÁ ---------- */
SET IDENTITY_INSERT danh_gia ON;
INSERT INTO danh_gia (id, id_khach_hang, id_san_pham, so_sao, noi_dung, trang_thai, ngay_tao, phan_hoi_cua_shop, hinh_anh_video, id_hoa_don_chi_tiet, so_luot_thich) VALUES
(1, 2, 12, 5, N'Bioré essence thấm nhanh thật sự, bôi xong không bóng dầu. Da hỗn hợp như mình dùng hằng ngày rất ổn.', N'DA_DUYET', '2025-03-17 01:20:00', N'Cảm ơn chị Mai Anh đã tin dùng sản phẩm tại SUNOVA ạ!', NULL, 11, 6),
(2, 2, 14, 4, N'Nâng tông nhẹ, da sáng hơn, nhưng vùng mũi hơi đọng nếu bôi nhiều. Giao hàng nhanh.', N'DA_DUYET', '2025-03-18 01:20:00', N'SUNOVA cảm ơn góp ý của chị, chị lấy lượng vừa đủ và tán mỏng nhé ạ.', NULL, 12, 3),
(3, 3, 18, 5, N'Kiềm dầu tốt, đi làm cả ngày mặt vẫn khô thoáng. Sẽ mua lại.', N'DA_DUYET', '2025-07-06 20:40:00', NULL, NULL, 38, 4),
(4, 3, 5, 4, N'Hàng Mỹ nên không ghi PA như hàng Nhật, nhưng bôi rất khô thoáng, hợp da dầu mụn.', N'DA_DUYET', '2025-07-11 21:40:00', N'Cảm ơn anh Phúc đã đánh giá ạ!', NULL, 39, 2),
(5, 4, 20, 5, N'Kem mỏng, căng bóng da, da khô mùa lạnh dùng rất hợp. Đóng gói cẩn thận.', N'DA_DUYET', '2025-10-15 19:05:00', N'Cảm ơn chị Trang, chúc chị luôn có làn da khỏe đẹp ạ!', NULL, 55, 8),
(6, 4, 17, 4, N'Dưỡng ẩm tốt, không vệt trắng. Giá hơi cao nhưng xứng đáng.', N'DA_DUYET', '2025-10-14 16:05:00', NULL, NULL, 56, 1),
(7, 1, 2, 5, N'Anessa gel mát, bôi xong không bết, hợp mùa hè Hà Nội.', N'DA_DUYET', '2025-11-20 19:45:00', N'Cảm ơn chị Lan đã ủng hộ SUNOVA ạ!', NULL, 67, 7),
(8, 1, 4, 3, N'Kiềm dầu ổn nhưng buổi chiều hơi xỉn màu da, chắc do da mình nhiều dầu. Nhân viên tư vấn nhiệt tình.', N'DA_DUYET', '2025-11-21 17:45:00', N'SUNOVA cảm ơn chị đã chia sẻ, chị có thể dùng thêm giấy thấm dầu buổi trưa nhé ạ.', NULL, 68, 1),
(9, 5, 15, 5, N'Đi đá bóng ra nhiều mồ hôi mà không bị cay mắt, kem bền thật.', N'DA_DUYET', '2025-12-27 01:10:00', NULL, NULL, 72, 2),
(10, 2, 9, 5, N'Tông hồng lên da tự nhiên, dùng thay kem lót luôn. Rất thích.', N'DA_DUYET', '2026-01-14 14:30:00', N'Cảm ơn chị Mai Anh ạ!', NULL, 81, 5),
(11, 6, 3, 5, N'Da nhạy cảm của mình không bị châm chích như các loại khác. Hàng chính hãng, có tem đầy đủ.', N'DA_DUYET', '2026-02-16 14:25:00', N'Cảm ơn chị Hân đã tin tưởng SUNOVA ạ!', NULL, 93, 11),
(12, 6, 8, 5, N'Kem vật lý mà không bị vệt trắng, rau má làm dịu da rõ.', N'DA_DUYET', '2026-02-14 16:25:00', NULL, NULL, 94, 4),
(13, 7, 10, 4, N'Tông tím hợp da mình bị vàng, lên da tự nhiên. Trừ 1 sao vì hơi ướt da lúc mới bôi.', N'DA_DUYET', '2026-05-31 18:55:00', N'Cảm ơn chị Như đã góp ý ạ, chị chờ khoảng 1 phút cho kem thấm rồi trang điểm nhé.', NULL, 129, 3),
(14, 7, 6, 5, N'Vichy UV-Age mỏng như nước, không nhờn, dùng dưới lớp trang điểm rất ổn.', N'DA_DUYET', '2026-05-29 21:55:00', NULL, NULL, 130, 4),
(15, 6, 16, 5, N'Bản có màu che được vùng đỏ quanh mũi, không gây mụn. Đáng tiền.', N'DA_DUYET', '2026-07-19 18:40:00', NULL, NULL, 162, 6);
