/* ---------- 13. NỘI DUNG TRANG ---------- */
SET IDENTITY_INSERT cau_hoi_thuong_gap ON;
INSERT INTO cau_hoi_thuong_gap (id, cau_hoi, tra_loi, chu_de, trang_thai) VALUES
(1, N'Kem chống nắng nên bôi lại sau bao lâu?', N'Nên bôi lại sau mỗi 2 giờ khi ở ngoài trời, và ngay sau khi bơi hoặc ra nhiều mồ hôi.', N'Sử dụng', 1),
(2, N'SPF và PA khác nhau thế nào?', N'SPF thể hiện khả năng chống tia UVB (gây cháy nắng), PA thể hiện khả năng chống tia UVA (gây sạm, lão hóa). PA là hệ thống của Nhật, hàng Mỹ/châu Âu thường không ghi PA.', N'Kiến thức', 1),
(3, N'Da dầu nên chọn loại nào?', N'Nên chọn dạng gel, tinh chất hoặc fluid có công dụng kiềm dầu, không gây bít tắc.', N'Tư vấn', 1),
(4, N'Ở trong nhà có cần chống nắng không?', N'Có, tia UVA xuyên qua cửa kính; nên dùng nếu ngồi gần cửa sổ.', N'Sử dụng', 1),
(5, N'Sản phẩm tại SUNOVA có chính hãng không?', N'Toàn bộ sản phẩm nhập từ nhà phân phối chính thức, quản lý theo lô và hạn sử dụng rõ ràng.', N'Chính sách', 1),
(6, N'Chính sách đổi trả thế nào?', N'Đổi trả trong 7 ngày kể từ khi nhận hàng nếu sản phẩm còn nguyên tem và hóa đơn.', N'Chính sách', 1);
SET IDENTITY_INSERT cau_hoi_thuong_gap OFF;
GO
