/* ---------- 15. KIỂM TRA NHANH ---------- */
SELECT 'nhan_vien' bang, COUNT(*) so_dong FROM nhan_vien UNION ALL SELECT 'khach_hang',COUNT(*) FROM khach_hang UNION ALL SELECT 'san_pham',COUNT(*) FROM san_pham
UNION ALL SELECT 'chi_tiet_san_pham',COUNT(*) FROM chi_tiet_san_pham UNION ALL SELECT 'lo_hang',COUNT(*) FROM lo_hang UNION ALL SELECT 'hoa_don',COUNT(*) FROM hoa_don UNION ALL SELECT 'danh_gia',COUNT(*) FROM danh_gia;
-- Tồn kho phải bằng tổng lô (kết quả rỗng = đúng):
SELECT c.sku, c.so_luong_ton, SUM(l.so_luong_con) tong_lo FROM chi_tiet_san_pham c JOIN lo_hang l ON l.id_chi_tiet_san_pham=c.id AND l.trang_thai=1 GROUP BY c.id,c.sku,c.so_luong_ton HAVING c.so_luong_ton<>SUM(l.so_luong_con);
GO
